"""Create page/gate crosswalk and the product-facing review receipt from measured ledgers."""
from pathlib import Path
import csv,gzip,hashlib,json,collections,shutil
root=Path(__file__).resolve().parents[2];out=root/'output/interface-five';pub=root/'docs/reviews/25-interface-elements'
def feature(file,k):
 paths=file.lower();s=(k or '').lower()
 if not k:return 'Runtime record or computed value · no static string identity'
 if 'signin' in paths:return 'Legacy sign-in · account selection, cancellation, denied completion and return'
 if paths.endswith('/app.tsx') and k in ['Quit Dockit','Show or hide Dockit','Hide Dockit','Hide others','Copy','Paste','Edit','About Dockit','Dockit ({0} to toggle)']:return 'macOS application and tray menus · native menu/popover outside the web document'
 if any(p in paths for p in ['conflict','recovery','backup','syncmerge']):return 'Conflict and recovery · conflicting cloud records, saved copies and restore confirmation'
 if any(p in paths for p in ['workspaceassign','workspace_assign','suite_workspace','suiteWorkspace','dianeaction','taskexecution','workflowstatus','taskpreparation']):return 'Assignment and execution · workspace/recipient selection, approval/revision states and external run details'
 if any(p in paths for p in ['meeting','citation','mynit']):return 'Meeting intake · specific saved analyses, linked tasks, citation revisions and missing passages'
 if any(p in paths for p in ['cloud','account','syncprogress','sync_merge']):return 'Accounts and sync · live identity, provider/configuration failure, sync conflict, recovery and retry'
 if any(p in paths for p in ['project','goal_plan']):return 'Project and multi-day project planning · editing, stale plans, failed saves, proposals and scheduled work'
 if any(p in paths for p in ['mission','focus','tracking','orbital']):return 'Focus · active/paused/completed missions, orbital map details and historical state'
 if any(p in paths for p in ['schedule','planning','plan_screen','plan.ts','stepproposal']):return 'Day plan and suggestions · constraints, generated proposals, apply/discard and provider failures'
 if any(p in paths for p in ['archive','progress']):return 'Search and progress · mixed filters, retained history, limits and unavailable records'
 if any(p in paths for p in ['goal','routine']):return 'Goals and routines · long-term work, reminders, destructive choices and history'
 if any(p in paths for p in ['settings','provider','devtools','material']):return 'Settings · storage, appearance, AI configuration, developer tools and integrations'
 if any(p in paths for p in ['update','screenshot','resize','nativefile','files.dart']):return 'Platform-owned operations · update phases, screenshot capture, OS file pickers and errors'
 if any(p in paths for p in ['document','editor','port.tsx']):return 'Embedded document/editor · weekly files, recovery, host reconciliation and edit decisions'
 if any(p in paths for p in ['task','sticky_store','models','persistence','api.ts']):return 'Notebook and task operations · date/finish states, long text, retry, persistence and validation'
 return 'Shell and other controls · transient navigation, notices, integrations or data-dependent text'
allrows=collections.defaultdict(collections.Counter);examples=collections.defaultdict(set);pages=collections.defaultdict(set)
for l in gzip.open(pub/'source-render-links.jsonl.gz','rt'):
 r=json.loads(l);group=feature(r['file'],r['key']);category=r['relation'];allrows[group][category]+=1
 if r['locale']=='en' and category=='no-candidate-on-captured-states':examples[group].add(str(r['key']))
 if r['candidatePages']:pages[group].update(s for states in r['candidatePages'].values() for s in states)
with (pub/'feature-gates.csv').open('w',newline='')as f:
 w=csv.writer(f);w.writerow(['feature or gate','source-key/locale cells with a candidate','no text match in captured states','unbound runtime-value cells','candidate-bearing states (any portal)','sample keys without text match']);
 for g,n in sorted(allrows.items(),key=lambda g:-g[1]['no-candidate-on-captured-states']):
  w.writerow([g,n['literal-or-template-candidate'],n['no-candidate-on-captured-states'],n['runtime-only-value'],' | '.join(sorted(pages[g])),' | '.join(sorted(examples[g])[:12])])
s=json.load(open(pub/'review-summary.json'));tot=s['rendered'];static=s['source']
def link(label,dst):return '['+label+']('+dst+')'
doc=['# 25. Dockit five-cycle element review and Flutter exports','','**Status:** Reviewed current local product source and the states listed below. The evidence preserves partial observations and unexercised feature gates.','','## What was reviewed','','Each source row has a real file span, a locale, a build reference and five separate findings: source binding, catalog resolution, placeholder equivalence, residue checks and literal sentinel preservation. Runtime rows use a page/state, locale, actual selector/widget/AX path, text role and five separately captured observations. The five passes cover presence, localized wording, geometry, accessible role/name and repeatability. A missing observation stays missing. A native menu option, an accessibility node and a visible text run are distinct records.','','The matrix uses English, Simplified Chinese, Traditional Chinese, Cantonese, Japanese, Korean, French, German, Spanish and Portuguese. Fresh runs used synthetic notebook content, offline account/service fixtures and disposable app identities.','','| Surface and build scope | State renders | Elements observed five times | Partial elements | Actual cycle observations |','|---|---:|---:|---:|---:|']
for name,r in s['evidenceByProfile'].items():
 doc.append('| '+name+' | '+f"{r['stateRenders']:,} | {r['observedInAllFive']:,} | {r['partialFive']:,} | {r['reviews']:,} |")
doc+=['',f"**Measured totals.** {tot['stateRenders']:,} state renders and {tot['reviews']:,} element observations. {tot['observedInAllFive']:,} of {tot['uniqueLocaleStateElements']:,} observed locale/state/element identities have all five, with {tot['partialFive']:,} retained partial identities. {static['occurrences']:,} source occurrences × 10 locales × 5 passes produced {static['fiveChecks']:,} source findings. These totals describe independent evidence layers.",'','## Fixes and follow-up checks','','- Restored legible compact Focus-rail controls and timer terminology. Separated opening a notebook date from a task’s unfinished state. Allowed the compact Focus route summary to wrap. Verified compact/wide browser and native Mac views.','- Wrapped all six compact native settings tabs into two rows when necessary. The earlier Spanish Updates label extended beyond the Mac-window viewport in the bridge fixture. Repeated the Mac fixture and actual native WKWebView checks.','- Corrected singular and plural search-result and progress counts in the standalone, Flutter and embedded clients. The extra component and phone tests check one and two results across all ten locales. Underlying notebook contents and status codes are independent of these labels.','- The first original Cantonese relaunch could be mistaken for Traditional Chinese because the two globe labels coincide. The corrected guard verifies the distinct capture prompt before termination and after relaunch. All five fresh transitions on the exact exported simulator app passed. Original and corrective observations remain separate.','','## Scope and outstanding limits','',f"Of {static['localeOccurrenceRows']:,} source/locale cells, {s['sourceCandidateRelations']['literal-or-template-candidate']:,} share a literal or template with captured states, {s['sourceCandidateRelations']['no-candidate-on-captured-states']:,} have no candidate in their mapped surfaces, and {s['sourceCandidateRelations']['runtime-only-value']:,} are runtime-only expressions. Matching copy can occur in several components; these counts do not prove that a specific source branch executed.",'','The [feature and gate table](../reviews/25-interface-elements/feature-gates.csv) groups unmatched source cells by concrete workflow and lists representative source keys. The [source-to-render crosswalk](../reviews/25-interface-elements/source-render-links.jsonl.gz) retains every occurrence, source span and candidate page/state. Unmatched fragments, live user values and translated templates must be distinguished from a missing whole page. Real Google consent, real member assignments, live model responses, destructive recovery, OS document/screen-picking permissions, installer errors and physical-iPhone execution remain outside this local synthetic exercise.','', 'Native Android evidence is the installed Preview package on a synthetic emulator. Broader Android route evidence used the host Flutter renderer. Native iPhone XCTest exercised the actual installed app; the deeper Simulator route matrix used the actual iOS Flutter engine with isolated synthetic routes. Mac native evidence came from a separate Tauri debug bundle that checked its synthetic KB path before any read or write. Standalone Chromium, Tauri bridge fixtures and native WKWebView are separately identified. Supplemental component pages mount real production components with synthetic adapters; they do not establish live host/provider access.','','The original iPhone test has 32 partial Cantonese notebook/menu identities, preserved alongside the independent guarded retest. The simulator-engine menu has 118 partial accessibility identities caused by staggered menu exposure. All 118 have same-text language-option witnesses on all five native UIKit visits; those witnesses are linked separately, without filling missing cycles in another build. See [partial identities](../reviews/25-interface-elements/partial-elements.jsonl.gz).','','## Evidence and reproduction','','[Source ledger](../reviews/25-interface-elements/source-five.jsonl.gz) · [Rendered ledger](../reviews/25-interface-elements/rendered-five.jsonl.gz) · [State names and counts](../reviews/25-interface-elements/state-coverage.csv) · [Detailed summary](../reviews/25-interface-elements/review-summary.json) · [Checksums](../reviews/25-interface-elements/SHA256SUMS). The collectors and reconciliation code are in [scripts/interface-review](../../scripts/interface-review/).','','## Local phone exports','','[Release arm64 Android APK](../../output/clients/android-release/Dockit-arm64-v8a-release.apk) · [armeabi-v7a APK](../../output/clients/android-release/Dockit-armeabi-v7a-release.apk) · [x86_64 APK](../../output/clients/android-release/Dockit-x86_64-release.apk) · [Preview APK](../../output/clients/Dockit-debug.apk) · [Simulator app](../../output/clients/ios-simulator/Dockit.app) · [Unsigned device app](../../output/clients/ios-device/Dockit.app) · [Unsigned IPA](../../output/clients/ios-device/Dockit-unsigned.ipa).','','The ARM64 release uses the original application ID and the historical production signer and advances version code 2029 to 2030. Preview has its own application ID and debug signer. The IPA contains the arm64 device app under §Payload/Dockit.app§; it needs provisioning and signing for a physical iPhone. The signed-in workbench consumes the [0.1.23 Dockit plugin](../../output/interface-five/diane-app-todo-plugin-0.1.23.tgz). The older instrumented simulator bundle and Cantonese-tested export are retained separately.']
(root/'docs/plans/25-interface-element-review.md').write_text('\n'.join(doc).replace('§',chr(96))+'\n')
